# the Low Countries, Mughal India, Southeast Asian kingdoms, pre-Classic Maya, the Bronze Age collapse, Brazil and 21st-century science
H,M='history','myth'
def X(id,title,lane,status,pr,start,ev,main,alts,src,img=None,end=None,changed=None,dateNote=None):
  d=dict(id=id,title=title,lane=lane,status=status,priority=pr,start=start,end=end,ev=ev,main=main,alts=alts,src=src,img=img)
  if changed:d['changed']=changed
  if dateNote:d['dateNote']=dateNote
  return d
E=[]
# --- part 1: Iberia and North Africa (Amazigh/Berber world, Canaries)
E+=[
X('sima-de-los-huesos',"Sima de los Huesos: the 'pit of bones' at Atapuerca",H,'confirmed',2,-430000,['fossil','genetic (ancient DNA)','archaeological'],
 "Deep inside the Cueva Mayor at Atapuerca in northern Spain, a 13-metre shaft called the Sima de los Huesos ('pit of bones') has yielded the remains of at least 28-29 individuals dated to about 430,000 years ago, excavated from the 1980s onwards by teams led by Juan Luis Arsuaga, Eudald Carbonell and José María Bermúdez de Castro. When first reported in 1993 they made up most of the world's Middle Pleistocene human fossil record. They show a mix of Neanderthal and more archaic traits, and nuclear DNA recovered in 2016 (Meyer et al., Nature) placed them on the Neanderthal side of the split from Denisovans, making it the oldest human DNA then sequenced. A single finely made quartzite hand-axe, nicknamed 'Excalibur', was found among the bones. Nearby Atapuerca sites (Gran Dolina, Sima del Elefante) contain some of the oldest human fossils in western Europe, over 800,000 years old.",
 [('Deliberate deposition','Many of the excavators argue that bodies were deliberately dropped into the pit by other humans, which would be among the earliest evidence of funerary behaviour; the lone hand-axe has been read as a possible offering.'),
  ('Natural accumulation','Other researchers suggest the bodies could have arrived through natural processes such as debris flows, carnivore activity or falls, and caution against reading symbolism into a single tool.'),
  ('Classification','The fossils were once assigned to Homo heidelbergensis; since the DNA results most researchers treat them as early members of the Neanderthal lineage, which has reshaped debates over when Neanderthals and modern humans diverged.')],
 ['wiki:Sima_de_los_Huesos_hominins','wiki:Archaeological_Site_of_Atapuerca','doi:10.1038/nature17405'],'Sima de los Huesos hominins',dateNote='c. 430,000 years ago',
 changed="Reported 1993 as pre-Neanderthals; mitochondrial DNA (2013) unexpectedly matched Denisovans; nuclear DNA (2016) showed they belong to the Neanderthal lineage."),
X('tartessos',"Tartessos: Iberia's lost kingdom, Tarshish, and Atlantis",H,'disputed',2,-900,['archaeological','textual (Greek, biblical)','epigraphic'],
 "Greek writers described Tartessos as a rich city and kingdom beyond the Pillars of Hercules, near the mouth of the Guadalquivir in south-western Spain, famous for silver, tin and copper; Herodotus tells of a long-lived Tartessian king, Arganthonios, who welcomed Phocaean Greek traders. Archaeology has identified a Tartessian culture in Andalusia and southern Portugal from the Late Bronze Age to about the 5th century BCE, shaped by intense contact with Phoenician colonists at Gadir (Cádiz). It is known for gold hoards such as the El Carambolo treasure (found 1958), the Southwest script with around a hundred inscriptions in an undeciphered language, and the burned and buried 5th-century BCE building at Casas del Turuñuelo (excavated from 2015). No capital city has ever been found.",
 [('Tarshish','Many biblical scholars have identified Tarshish, the distant source of metals for Solomon\'s and Tyre\'s ships in the Hebrew Bible, with Tartessos; others link Tarshish to Tarsus in Anatolia or elsewhere.'),
  ('Atlantis connection','In 1922 the German archaeologist Adolf Schulten proposed that Tartessos was the real-world source of Plato\'s Atlantis, buried under the Doñana marshes. In 2011 a team led by Richard Freund claimed evidence in Doñana; Spanish researchers on the wider project described those claims as fanciful (speculative).'),
  ('A state or a culture?','Archaeologists debate whether \'Tartessos\' was a centralised kingdom with a lost capital or a looser network of communities that Greek writers summed up under one name.')],
 ['wiki:Tartessos','wiki:Treasure_of_El_Carambolo','wiki:Southwest_Paleohispanic_script'],'Tartessos',end=-500,dateNote='c. 9th-5th century BCE'),
X('lady-of-elche',"The Lady of Elche: Iberian masterpiece or forgery?",H,'disputed',3,-400,['archaeological','art-historical','pigment analysis'],
 "The Lady of Elche (Dama de Elche) is a painted limestone bust of a woman wearing an elaborate headdress with large wheel-shaped side ornaments, found in 1897 at La Alcudia near Elche in eastern Spain. Generally dated to the 4th century BCE, it is regarded as a masterpiece of Iberian sculpture showing Greek influence and may have served as a funerary urn, as it has a cavity in the back. It was sold to the Louvre within weeks of its discovery, returned to Spain in 1941 and is in the National Archaeological Museum in Madrid.",
 [('Genuine Iberian work','Most Spanish archaeologists accept the bust as ancient. A 2005 study by the Spanish National Research Council (CSIC) of microscopic pigment traces found materials consistent with antiquity and no modern pigments.'),
  ('Forgery claim','In 1995 the American art historian John F. Moffitt argued in \'Art Forgery: The Case of the Lady of Elche\' that the bust was a 19th-century fake, perhaps by the restorer Francisco Pallás, citing stylistic differences from other Iberian sculpture. Doubts had first been raised in 1906. Experts in Iberian archaeology have rejected the claim.'),
  ('Goddess or noblewoman?','Interpretations range from a portrait of a high-status woman to a priestess or a goddess associated with the Carthaginian Tanit.')],
 ['wiki:Lady_of_Elche'],'Lady of Elche',dateNote='4th century BCE (conventional date)'),
X('santiago-compostela-tomb',"The tomb of St James at Santiago de Compostela",M,'disputed',2,814,['textual (medieval)','archaeological','tradition'],
 "According to Compostela tradition, the hermit Pelagius saw mysterious lights over the Libredon forest in Galicia in the early 9th century (usually 814), and Bishop Theodemir identified a tomb there as that of the apostle James, son of Zebedee, who had been executed in Jerusalem around 44 CE. Medieval legend held that James had preached in Hispania and that his disciples brought his body by a stone boat to Galicia. King Alfonso II built a church, the cult grew rapidly, and the Way of St James became one of the great pilgrimage routes of medieval Europe; the Romanesque cathedral was begun in 1075. Excavations under the cathedral revealed a Roman-era necropolis, and the relics, hidden in 1589 against an English attack, were rediscovered in 1879 and declared authentic by Pope Leo XIII in 1884.",
 [('Faith tradition','The Catholic Church venerates the remains as those of the apostle; the pilgrimage revived strongly in the late 20th century and hundreds of thousands of people now walk the routes each year.'),
  ('Historical scepticism','Most historians note that there is no early evidence that James ever went to Spain or was buried there, and see the 9th-century discovery as serving the Christian kingdom of Asturias in its struggle with al-Andalus; later legend made James \'Matamoros\', the Moor-slayer, appearing at the (probably legendary) battle of Clavijo.'),
  ('Priscillian hypothesis','Some writers have suggested that the tomb venerated at Santiago actually held Priscillian, a 4th-century Galician bishop executed for heresy at Trier in 385 whose body was returned to Galicia and revered as a martyr (speculative).'),
  ('Lights and stars','The name Compostela is popularly explained as Campus Stellae, \'field of the star\', after Pelagius\' lights, and the route became linked with the Milky Way; many linguists prefer a derivation from a Latin word for a burial ground.')],
 ['wiki:Santiago_de_Compostela_Cathedral','wiki:James_the_Great','wiki:Camino_de_Santiago','wiki:Priscillian'],'Santiago de Compostela Cathedral',dateNote='Tomb reportedly found c. 814 CE'),
X('abbas-ibn-firnas',"Abbas ibn Firnas: the flying man of Córdoba",H,'disputed',3,875,['textual (late source)'],
 "Abbas ibn Firnas (c. 810-887) was a polymath at the Umayyad court of Córdoba in al-Andalus: a poet, musician, astronomer and engineer credited with a planetarium-like device, a water clock and a method of cutting rock crystal and making glass. About seven centuries after his death the historian Ahmad al-Maqqari (d. 1632) wrote that Ibn Firnas covered himself in feathers, attached wings and launched himself from a height, flying 'a considerable distance' before landing badly and hurting his back, because he had not made himself a tail. A ninth-century verse quoted by al-Maqqari is the only earlier hint of the event.",
 [('Early gliding attempt','Many historians of flight accept that Ibn Firnas probably made some kind of gliding attempt, comparable to the reported jump of the English monk Eilmer of Malmesbury around 1000-1010; he is honoured by a statue at Baghdad International Airport, a bridge in Córdoba and a lunar crater.'),
  ('Late and thin evidence','Others stress that the story rests on a single 17th-century source that does not cite its authority, so the details cannot be checked.'),
  ('\'Armen Firman\' confusion','Some modern books say Ibn Firnas was inspired by an earlier parachute-like jump by one \'Armen Firman\' in Córdoba; this figure appears in no primary source and is probably a garbled Latinised form of Ibn Firnas\' own name.')],
 ['wiki:Abbas_ibn_Firnas','wiki:Eilmer_of_Malmesbury'],'Abbas ibn Firnas'),
X('guanches',"The Guanches: Amazigh islanders of the Canaries",H,'confirmed',2,-500,['genetic (ancient DNA)','archaeological','linguistic','textual (conquest accounts)'],
 "When Europeans reached the Canary Islands in the 14th-15th centuries they found them inhabited by peoples, collectively called Guanches (strictly, the people of Tenerife), who herded goats, grew barley, lived in caves and stone houses, and on Tenerife mummified some of their dead. Their languages were related to the Berber (Amazigh) languages of North Africa, and in 2017 the first ancient-genome study confirmed a North African origin, most similar to ancient and modern Amazigh populations. They probably arrived in the 1st millennium BCE or early 1st millennium CE, though how is unclear, since they appear to have had no seagoing boats at contact. The Castilian conquest (1402-1496) killed or enslaved many and the rest were assimilated; the Guanche languages died out by the 17th century, but traces survive, including Silbo Gomero, the whistled language of La Gomera.",
 [('How they arrived','Some researchers think the islands were settled by North Africans brought or encouraged by Phoenician-Punic or Roman traders; others suggest independent voyages with seafaring knowledge later lost.'),
  ('Atlantis and lost races','From the 19th century some writers claimed the Guanches were survivors of Atlantis or a lost white race, partly because of reports of fair hair and the islands\' remote position; genetics and linguistics place them firmly within North African populations (speculative claims rejected).'),
  ('Pyramids of Güímar','Stepped stone platforms at Güímar on Tenerife were promoted by Thor Heyerdahl in the 1990s as possible links to ancient pyramid builders; archaeologists date them to the 19th century, when farmers cleared stones from their fields.')],
 ['wiki:Guanches','wiki:Pyramids_of_Güímar','wiki:Silbo_Gomero','doi:10.1016/j.cub.2017.09.059'],'Guanches',end=1496),
X('dihya-kahina',"Dihya, 'al-Kahina': the Amazigh warrior-queen who fought the Umayyads",H,'disputed',2,690,['textual (medieval Arabic chronicles)','oral tradition'],
 "Dihya, known in Arabic sources as al-Kahina ('the priestess' or 'soothsayer'), was a 7th-century Amazigh (Berber) leader in the Aurès mountains of present-day Algeria. After the Umayyad general Hassan ibn al-Nu'man took Carthage, she defeated his army at the battle of the Meskiana (c. 698) and pursued him back into Libya, ruling much of the Maghreb for several years. Chroniclers say she then adopted a scorched-earth policy that alienated oasis and town dwellers, and that she was defeated and killed around 701-703 at a well still called Bir al-Kahina. Before the last battle she reportedly sent her sons to join the Arabs. Most details come from Arab historians writing centuries later, notably Ibn Khaldun.",
 [('Religion','Interpretations of her faith differ: some, reading Ibn Khaldun, have described her as Jewish or as leading Judaised Berber tribes; others, including the historians Mohamed Talbi and Gabriel Camps, think she was more probably Christian; still others see a traditional Amazigh religious role behind the title \'priestess\'.'),
  ('Legend and history','Her prophetic powers, her adoption of an Arab captive and her foreknowledge of her death are widely regarded as legendary embellishment, and some historians doubt parts of the chronology.'),
  ('Shifting symbol','She has been claimed in turn as an Algerian national heroine, an Amazigh cultural icon, a Jewish heroine and a feminist symbol; a statue of her stands in Khenchela, Algeria.')],
 ['wiki:Kahina','wiki:Hassan_ibn_al-Nu\'man'],'Kahina',dateNote='Active c. 690s-701/703 CE'),
X('tin-hinan',"Tin Hinan: the ancestral queen of the Tuareg",H,'disputed',3,350,['archaeological','oral tradition','radiocarbon'],
 "Tuareg tradition in the Hoggar (Ahaggar) of southern Algeria holds that a noblewoman named Tin Hinan came from the Tafilalt oasis in Morocco with a companion, Takamat, and became the founding ancestress of the noble Tuareg lineages. A monumental stone tomb at Abalessa, opened in 1925 by the adventurer Byron Khun de Prorok with French military support and studied more carefully in 1933, contained the skeleton of a tall woman lying on a wooden bed, adorned with gold and silver bracelets and beads, together with a coin impression of the Roman emperor Constantine. She is usually dated to the 4th-5th century CE, and her remains are in the Bardo Museum in Algiers.",
 [('Tomb of the legendary queen','Many writers and the Tuareg themselves identify the Abalessa burial with the Tin Hinan of tradition, which would make it a rare case of an oral ancestress matched to a real grave.'),
  ('Unproven identification','Archaeologists note that nothing in the tomb names its occupant; the link to the legend was made by its excavators, and the building may have been a fortified structure reused for the burial.'),
  ('Matrilineal society','The legend is often connected with the relatively high status of women and matrilineal descent among the Tuareg.')],
 ['wiki:Tin_Hinan','wiki:Tuareg_people'],'Tin Hinan',dateNote='Burial usually dated 4th-5th century CE'),
X('taforalt',"Taforalt: North Africa's oldest cemetery and its genetic surprise",H,'confirmed',3,-13000,['archaeological','genetic (ancient DNA)','dental'],
 "Grotte des Pigeons at Taforalt in north-eastern Morocco holds what is probably the oldest known cemetery in North Africa: dozens of Iberomaurusian hunter-gatherers buried between about 15,100 and 14,000 years ago. Their teeth show unusually high rates of tooth decay, linked to a diet rich in starchy wild plants such as acorns and pine nuts, thousands of years before farming (Humphrey et al. 2014). In 2018 seven individuals produced the oldest nuclear genomes then known from Africa (van de Loosdrecht et al., Science): they carried a large Near Eastern-related component, most similar to the Natufians of the Levant, plus a component related to sub-Saharan Africans.",
 [('Migration into Africa','The original study suggested that the Near Eastern-related ancestry reflects movement of people into North Africa before the Holocene.'),
  ('Back-migration debate','Other geneticists have modelled the data differently, arguing that Iberomaurusian-related ancestry contributed to the Natufians rather than the other way round, and that some \'Eurasian\' and \'African\' labels for lineages long present in North Africa are misleading. The direction of gene flow remains debated.'),
  ('Sahara as a barrier','A 2025 study of 7,000-year-old Green Sahara individuals from Takarkori, Libya, found a separate, long-isolated North African lineage, suggesting the Green Sahara was not a major corridor between north and sub-Saharan Africa.')],
 ['wiki:Taforalt','doi:10.1126/science.aar8380','doi:10.1073/pnas.1318176111'],'Taforalt',dateNote='Burials c. 15,100-14,000 years ago'),
X('msoura-stone-circle',"Msoura: Morocco's stone circle and the tomb of the giant Antaeus",M,'myth-legend',3,-300,['archaeological','textual (classical)','folklore'],
 "Msoura (Mzora), about 15 km south-east of Asilah in northern Morocco, is an oval ring of 167 standing stones surrounding a large burial mound about 58 by 54 metres; one stone, El Uted ('the peg'), is over 5 metres tall. It is usually dated to around the 4th-3rd century BCE and may relate to the beginnings of the Kingdom of Mauretania. Local legend calls it the tomb of the giant Antaeus, the Libyan wrestler defeated by Heracles in Greek myth; the Roman writer Plutarch reports that the general Sertorius dug open a tomb said to be that of Antaeus near Tingis (Tangier) and found a skeleton 60 cubits long, before reburying it. In January 2025 Morocco listed the site as national heritage.",
 [('Mauretanian royal tomb','Archaeologists generally interpret Msoura as a monumental tomb of a local elite or early royal family, with parallels to other North African tumuli.'),
  ('Antaeus and Sertorius','Some writers suggest Msoura may be the tomb Sertorius opened; this cannot be confirmed, and stories of giant bones are common worldwide, often arising from fossil animal bones (speculative).'),
  ('Atlantic megalithic link','Its circle of standing stones has led some to compare it with Atlantic European megaliths, which are thousands of years older; most archaeologists see it as a local North African tradition.')],
 ['wiki:Msoura','wiki:Antaeus','wiki:Quintus_Sertorius'],'Msoura',dateNote='Usually dated 4th-3rd century BCE'),
]
# --- part 2: Indigenous Australia, Melanesia and early hominins
E+=[
X('murujuga-rock-art',"Murujuga: a million petroglyphs and the world's largest rock-art gallery",H,'confirmed',2,-45000,['archaeological','rock art','oral tradition'],
 "Murujuga, the Burrup Peninsula and Dampier Archipelago in the Pilbara of Western Australia, holds what is often described as the world's largest concentration of rock engravings: around a million petroglyphs at some 2,500 recorded sites, made over many millennia by the ancestors of today's custodians, the Yaburara, Ngarluma, Mardudhunera, Yindjibarndi and Wong-Goo-Tt-Oo peoples (many Yaburara people were killed in the Flying Foam massacre of 1868). The oldest are commonly estimated at tens of thousands of years (figures of 40,000-50,000 years are often cited, though direct dating of engravings is difficult). Images include human figures, faces, kangaroos, emus, marine animals and many depictions of the thylacine, which disappeared from mainland Australia about 3,000 years ago. The engravings also record environmental change as rising seas after the last Ice Age turned a coastal range into islands. In July 2025 the Murujuga Cultural Landscape was inscribed on the UNESCO World Heritage List.",
 [('Industry and preservation','Since the 1960s port, iron-ore and gas developments have destroyed or moved many engravings, and scientists disagree with government and industry over whether industrial emissions are damaging the rock surfaces; a monitoring programme began in 2023.'),
  ('Deep-time record','Many researchers see Murujuga as a continuous visual archive spanning from the Ice Age to the present, comparable in significance to European cave art; exact ages for individual motifs remain uncertain.'),
  ('Living tradition','Traditional custodians emphasise that the engravings are part of living law and story, not only an archaeological record.')],
 ['wiki:Burrup_Peninsula','wiki:Flying_Foam_massacre'],'Burrup Peninsula',dateNote='Engravings span tens of thousands of years to the recent past'),
X('wurdi-youang',"Wurdi Youang: an Aboriginal stone arrangement aligned with the sun?",H,'disputed',3,-1000,['archaeological','archaeoastronomical','oral tradition'],
 "Wurdi Youang, near Little River in Victoria, Australia, is an egg-shaped arrangement of about 100 basalt stones some 50 metres across, with three prominent waist-high stones at its highest, western end. It is on the traditional country of the Wathaurong people and was returned to the Wathaurong Aboriginal Co-operative in 2006. A 2013 study by Ray Norris, Duane Hamacher and colleagues argued that the arrangement's straight sides and outlying stones mark the setting points of the sun at the solstices and equinoxes, and that this is unlikely to be coincidence. Its age is unknown.",
 [('Solar observatory','Supporters argue that Wurdi Youang demonstrates sophisticated Aboriginal astronomical knowledge used for calendars and ceremony, consistent with recorded oral traditions of sky lore across Australia.'),
  ('Caution over alignments','Sceptics note that with many stones, some alignments can arise by chance, that the site has been disturbed since European settlement, and that no oral tradition specifically describing its astronomical use was recorded.'),
  ('Claims of great age','Popular reports have described it as possibly older than Stonehenge or even 11,000 years old, based on dates from other sites in the region; the arrangement itself has not been dated (speculative).')],
 ['wiki:Wurdi_Youang','url:https://arxiv.org/abs/1210.7000|Norris, R. P. et al. (2013) Wurdi Youang: an Australian Aboriginal stone arrangement with possible solar indications, Rock Art Research 30(1) (arXiv preprint)|paper'],'Wurdi Youang',dateNote='Age unknown; date shown is a placeholder for a pre-contact construction'),
X('emu-in-the-sky',"The Emu in the Sky and Aboriginal astronomy",M,'myth-legend',2,1840,['oral tradition','ethnographic','astronomical'],
 "Across much of Australia, Aboriginal peoples recognise a constellation made not of stars but of the dark dust lanes of the Milky Way: the Emu in the Sky, whose head is the Coalsack nebula beside the Southern Cross and whose body stretches towards Scorpius. Its changing position through the year signals when emus lay eggs and when to collect them. Rock engravings in Ku-ring-gai Chase National Park near Sydney include an emu in the same pose as the sky emu. Records of Aboriginal astronomy go back to the settler William Stanbridge, who in 1857 published star lore of the Boorong people of north-western Victoria. In 2010 astronomers Duane Hamacher and David Frew argued that a Boorong story about a star called Collowgulloric War records the 1840s outburst of the star Eta Carinae.",
 [('Practical calendar','Researchers emphasise that sky knowledge was tied to seasons, food resources, law and navigation, a practical and ceremonial system rather than abstract star-gazing.'),
  ('\'World\'s first astronomers\'','Some writers call Aboriginal Australians the world\'s first astronomers given the continuity of their cultures over tens of thousands of years; others caution that the antiquity of any particular sky story cannot be directly measured.'),
  ('Diversity of traditions','The same dark shape is read differently in different nations; for the Wardaman, for example, the Coalsack is the head of a lawman, not an emu.')],
 ['wiki:Australian_Aboriginal_astronomy','url:https://arxiv.org/abs/1010.4610|Hamacher, D. W. & Frew, D. J. (2010) An Aboriginal Australian record of the Great Eruption of Eta Carinae, Journal of Astronomical History and Heritage (arXiv preprint)|paper'],'Emu in the sky',dateNote='Traditions of great but unknown age; first written records 1840s-1850s'),
X('kula-ring',"The Kula ring: shell valuables that circle the islands",H,'confirmed',3,1915,['ethnographic','oral tradition','archaeological'],
 "In the Massim islands of Milne Bay, Papua New Guinea, including the Trobriand Islands, men make long canoe voyages to exchange two kinds of ceremonial valuables: red shell-disc necklaces (soulava or veigun), which travel clockwise around a ring of island communities, and white shell armbands (mwali), which travel anticlockwise. The objects are not kept permanently but passed on, and their histories and the partnerships they create bring prestige. The anthropologist Bronisław Malinowski, who lived in the Trobriands in 1915-18, made the Kula famous in Argonauts of the Western Pacific (1922), asking why people would risk dangerous ocean voyages to give away apparently useless trinkets. The exchange continues today.",
 [('Gift economy','Marcel Mauss used the Kula in The Gift (1925) to argue that exchange creates social obligations, an idea that became central to anthropology and economics debates about non-market economies.'),
  ('Women and wealth','Annette Weiner, revisiting the Trobriands in the 1970s, argued that Malinowski had overlooked women\'s wealth and exchanges, which were essential to the system.'),
  ('Antiquity','Archaeologists have looked for the roots of the Kula in older Massim trade networks; when the ring as described by Malinowski took shape is uncertain.')],
 ['wiki:Kula_ring','wiki:Argonauts_of_the_Western_Pacific'],'Kula ring',dateNote='Documented 1915-18; origins older and uncertain'),
X('teouma-cemetery',"Teouma: the first Pacific islanders and their missing skulls",H,'confirmed',3,-1000,['archaeological','genetic (ancient DNA)','radiocarbon'],
 "At Teouma on Efate island, Vanuatu, archaeologists found the oldest known cemetery in the Pacific Islands, used about 3,000-3,200 years ago by people of the Lapita culture, the first settlers of Remote Oceania. Many burials had their skulls removed after decomposition; some were replaced with cone-shell rings, and in one burial three skulls lay on the chest of a headless body. The site was found by chance in 2003 during earthworks for a prawn farm. Finely stamped Lapita pottery accompanied the dead, including a decorated pot holding a human skull, covered by an upturned flat-bottomed dish used as a lid. In 2016 ancient DNA from Teouma individuals (Skoglund et al., Nature) showed that the first settlers had almost entirely East Asian-related ancestry, with Papuan ancestry arriving in Vanuatu later.",
 [('Skull rituals','Archaeologists interpret skull removal as ancestor veneration, a practice known from later Melanesian societies and from other regions such as the Neolithic Near East.'),
  ('Population replacement debate','The genetic results suggested that modern ni-Vanuatu largely descend from later Papuan-ancestry arrivals while keeping Austronesian languages; researchers continue to debate how this language and population turnover happened.'),
  ('Wider pattern','Teouma has become a key site in tracing the rapid Lapita expansion from the Bismarck Archipelago to Tonga and Samoa within a few centuries.')],
 ['wiki:Teouma','doi:10.1038/nature19844'],'Teouma',dateNote='c. 3,000-3,200 years ago'),
X('denisovans-papua',"Ghost ancestors in Papua: Denisovan DNA in Melanesians",H,'confirmed',3,-45000,['genetic'],
 "The Denisovans, an archaic human group known mainly from DNA first read from a finger bone in Siberia's Denisova Cave in 2010, left their largest genetic legacy far away: in Papuans, Aboriginal Australians and other Near Oceanians, who carry several per cent Denisovan ancestry (Philippine Aeta groups carry even more). In 2019 Guy Jacobs and colleagues reported that Papuans carry DNA from at least two deeply divergent Denisovan populations, one of which may have interbred with modern humans as recently as about 30,000 years ago, suggesting Denisovans may have survived in or near New Guinea until surprisingly late. No Denisovan fossil has yet been found east of the Wallace Line.",
 [('Wallacea or Sundaland?','Some researchers think Denisovans crossed the deep-water Wallace Line, as Homo floresiensis and Homo luzonensis ancestors did; others suggest the mixing happened further west, in Sundaland, before modern humans crossed.'),
  ('Adaptive genes','Studies suggest some Denisovan gene variants in Papuans affect immunity and possibly adaptation to different altitudes.'),
  ('Late survival','A late date for interbreeding implies that a Denisovan population persisted after most other archaic humans had vanished; this is debated because dating methods based on DNA segment lengths carry large uncertainties.')],
 ['wiki:Denisovan','doi:10.1016/j.cell.2019.02.035'],'Denisovan',dateNote='Interbreeding c. 45,000 and possibly c. 30,000 years ago'),
X('kongamato',"Kongamato: the 'boat-overwhelmer' of the Zambian swamps and living pterosaur claims",M,'myth-legend',3,1923,['eyewitness testimony','folklore'],
 "In his 1923 book In Witch-Bound Africa the British colonial official Frank Melland described the kongamato ('overwhelmer of boats'), a winged creature said to haunt the Jiundu swamps of north-western Zambia and to capsize canoes. He reported that local Kaonde men, shown pictures of a pterosaur, identified it as the kongamato. Later travellers added further reports from Zambia, Angola and the Congo, and cryptozoologists linked it to similar claims elsewhere, such as the ropen of Papua New Guinea, which some young-earth creationist writers promote as living pterosaurs.",
 [('Misidentified birds or bats','Sceptics, including the museum director Reay Smithers in 1957, suggested shoebills or saddle-billed storks, which can be aggressive near their nests; others proposed large fruit bats such as the hammer-headed bat.'),
  ('Fossil influence','In 1928 the Swedish palaeontologist Carl Wiman suggested the stories might have been influenced by pterosaur fossils dug up in Tanganyika (at Tendaguru) before the First World War, as news of them travelled.'),
  ('Living pterosaur','A few cryptozoologists have entertained the idea of a surviving pterosaur; palaeontologists note there are no pterosaur fossils younger than 66 million years (speculative).')],
 ['wiki:Kongamato','wiki:Tendaguru_Formation'],'Kongamato',dateNote='Described 1923'),
X('sahelanthropus-toumai',"Toumaï: a 7-million-year-old skull from Chad, and the femur that went missing",H,'disputed',2,-7000000,['fossil','biostratigraphic'],
 "In July 2001 a Franco-Chadian team found a distorted but nearly complete ape-like skull in the Djurab desert of northern Chad; President Idriss Déby nicknamed it Toumaï, 'hope of life' in the Daza language. Described by Michel Brunet and colleagues in Nature in 2002 as Sahelanthropus tchadensis, it is dated by associated animal fossils to about 7 million years ago, close to the time humans and chimpanzees are thought to have diverged, and far west of the East African Rift where most early hominin fossils come from. Its small canines and the forward position of the opening where the spinal cord enters the skull were taken as signs it was a hominin that walked upright.",
 [('Earliest known hominin','Brunet\'s team and supporters regard Sahelanthropus as the oldest known member of the human lineage; in 2022 Guillaume Daver and colleagues described a femur and ulnae from the site as showing habitual bipedalism combined with tree climbing.'),
  ('Ape, not hominin','Other researchers argue it may be an ape outside the human lineage, perhaps related to gorillas. A femur found among the site\'s animal bones by Poitiers graduate student Aude Bergeret in 2004 was described by Roberto Macchiarelli and colleagues in 2020 as not consistent with habitual upright walking, and they criticised the delay in publishing it.'),
  ('A disturbed site','Alain Beauvilain, who was present at the discovery, argued that the skull was found loose on the surface, not excavated, possibly after being reburied by nomads, which complicates dating.')],
 ['wiki:Sahelanthropus','doi:10.1038/nature00879','doi:10.1038/s41586-022-04901-z'],'Sahelanthropus',dateNote='c. 7 million years ago'),
X('happisburgh-footprints',"The Happisburgh footprints: Britain's first people, washed away within weeks",H,'confirmed',3,-900000,['ichnological (footprints)','geological','palaeomagnetic'],
 "In May 2013, waves at Happisburgh on the Norfolk coast of England stripped sand from the ancient Cromer Forest Bed and exposed around 50 human footprints pressed into estuarine mud. The team, led by Nick Ashton of the British Museum, recorded them with 3D photogrammetry before the tide destroyed them within about two weeks. Published in 2014, they date to roughly 850,000-950,000 years ago, making them the oldest known human footprints outside Africa. The prints seem to come from a group of adults and children, perhaps up to five people, at a time when Britain was joined to the continent by land (later Doggerland). Stone tools from Happisburgh are of similar age.",
 [('Who made them?','No bones have been found at Happisburgh; the most likely candidate is Homo antecessor, known from similarly old fossils at Gran Dolina, Atapuerca in Spain.'),
  ('Cold-climate pioneers','The finds suggest early humans could survive in a cool, northern climate far earlier than once thought, raising questions about clothing, shelter and fire.'),
  ('Fragile evidence','Because the prints no longer exist, all later analysis depends on the 3D records made in the field, a reminder of how chance exposure and erosion shape the archaeological record.')],
 ['wiki:Happisburgh_footprints','doi:10.1371/journal.pone.0088329'],'Happisburgh footprints',dateNote='c. 850,000-950,000 years ago'),
X('australopithecus-sediba',"Australopithecus sediba: the fossil found by a nine-year-old",H,'disputed',3,-1980000,['fossil','uranium-lead and palaeomagnetic dating'],
 "On 15 August 2008, nine-year-old Matthew Berger, exploring near his father Lee Berger's research area at Malapa in South Africa's Cradle of Humankind, spotted a fossil collarbone in a rock. It belonged to a juvenile skeleton (MH1, nicknamed Karabo), and a partial adult female skeleton (MH2) was found soon after. Described in 2010 as a new species, Australopithecus sediba, the fossils are about 1.98 million years old and combine a small australopith brain and climbing arms with a more human-like face, teeth and hand, and an unusual way of walking. The cave may have been a natural death trap at the base of a vertical shaft.",
 [('Ancestor of Homo?','Berger and colleagues proposed that A. sediba, or something like it, could be close to the ancestry of our genus Homo.'),
  ('Late cousin','Many others point out that fossils attributed to early Homo are older than Malapa, so sediba is more likely a late-surviving relative or a sister group of A. africanus, showing features evolved in parallel.'),
  ('Open science','The Malapa team made casts and scans widely available and invited many early-career researchers, an approach Berger later repeated with Homo naledi.')],
 ['wiki:Australopithecus_sediba','doi:10.1126/science.1184944'],'Australopithecus sediba',dateNote='c. 1.98 million years ago'),
]
# --- part 3: the Low Countries and Mughal India
E+=[
X('hunebedden',"The hunebedden: 'giants' beds' of Drenthe",H,'confirmed',3,-3400,['archaeological','early antiquarian texts'],
 "The hunebedden are megalithic passage graves in the north-east of the Netherlands, built from glacial boulders by people of the Western Group of the Funnelbeaker culture between about 3470 and 3250 BCE and used until about 2760 BCE. Of perhaps 100 original tombs, 54 survive, 52 of them in Drenthe, most along the Hondsrug ridge. They were reused by later Bronze Age peoples. The tombs attracted attention early: the first paper on them appeared in 1547, Titia Brongersma carried out the first known excavation in 1685, and in 1734 the government of Drenthe passed one of the earliest laws in Europe protecting antiquities.",
 [('Built by giants','The Dutch name is usually linked to old words for giants, and in 1660 the pastor Johan Picardt published a widely read book arguing that the tombs were built by giants who had come to Drenthe from the Holy Land via Scandinavia. The idea stayed popular in folklore and illustrations long after scholars dropped it.'),
  ('Ordinary farmers','Already in Picardt\'s time some, mainly German, scholars attributed the tombs to ordinary people. Modern archaeology shows they were collective graves of early farming communities, part of a Funnelbeaker tradition that may have built tens of thousands of such tombs across northern Europe.')],
 ['wiki:Megaliths_in_the_Netherlands','wiki:Funnelbeaker_culture'],'Megaliths in the Netherlands',end=-2760,dateNote='Built c. 3470-3250 BCE'),
X('flying-dutchman',"The Flying Dutchman: the ghost ship of the Cape",M,'myth-legend',2,1790,['folklore','sailors\' reports','literary'],
 "The Flying Dutchman is a legendary ghost ship doomed never to make port and to sail the seas forever, usually off the Cape of Good Hope. The legend probably grew out of the Golden Age of the Dutch East India Company (VOC); the oldest known printed mention is in John MacDonald's travel memoir of 1790 ('the sailors said they saw the Flying Dutchman'). An 1821 story in Blackwood's Magazine named the captain Hendrick van der Decken, who swore he would round the Cape even if it took until the day of judgment, and added the motif of the ghostly crew offering letters to long-dead people. Heinrich Heine's 1833 retelling inspired Richard Wagner's opera The Flying Dutchman (1843).",
 [('Real sightings','Sailors continued to report the ship. The best known account is in the published log of the royal princes\' cruise, recording that before dawn on 11 July 1881 off Australia a brig appeared in \'a strange red light as of a phantom ship all aglow\' and then vanished; the young Prince George, the future King George V, was on board. In the legend, seeing the ship is an omen of doom.'),
  ('Mirage at sea','The most widely accepted explanation for sightings is a superior mirage or Fata Morgana, in which ships beyond the horizon appear raised and distorted above the sea.'),
  ('Historical captain','Some sources suggest the legend was modelled on the 17th-century Dutch captain Bernard Fokke, famous for the speed of his voyages to Java and suspected of being in league with the Devil.')],
 ['wiki:Flying_Dutchman','wiki:Fata_Morgana_(mirage)'],'Flying Dutchman',dateNote='First printed mention 1790'),
X('st-elizabeth-flood-1421',"St Elizabeth's flood (1421): drowned villages and the cat in the cradle",H,'confirmed',3,1421,['documentary (chronicles)','geographical'],
 "During the night of 18-19 November 1421 a severe North Sea storm broke the dikes of the Grote Hollandse Waard, a large polder in what is now the Netherlands. A number of villages were swallowed and never rebuilt, and estimates of the dead range from 2,000 to 10,000. Much of the drowned land became tidal marsh; the area of today's Biesbosch National Park has been flooded ever since. The disaster also separated the rival cities of Dordrecht and Geertruidenberg, which had been fighting in the Hook and Cod wars.",
 [('The cat and the cradle','According to legend, after the flood people saw a cradle floating towards the dike with a cat leaping from side to side to keep it balanced; inside was a baby, still dry and asleep. The tale is linked to the name of Kinderdijk (\'children\'s dike\') and was painted by Lawrence Alma-Tadema in 1856.'),
  ('Legend and memory','Historians treat the cradle story as folklore without contemporary evidence, while the flood itself is well recorded. Medieval sources also blamed neglect of the dikes during the civil wars for making the disaster worse.')],
 ['wiki:St._Elizabeth\'s_flood_(1421)','wiki:Biesbosch','wiki:Kinderdijk'],'St. Elizabeth\'s flood (1421)',dateNote='18-19 November 1421'),
X('maastricht-mosasaurus',"The 'great animal of Maastricht': the fossil that proved extinction",H,'confirmed',3,1778,['fossil','documentary'],
 "In 1778 a chalk quarry in the Sint-Pietersberg near Maastricht produced a huge fossil skull with rows of teeth, the second such find there; it attracted the attention of the local physician Johann Leonard Hoffmann, who thought it was a crocodile, while others took it for a whale. When French revolutionary armies took Maastricht in 1795, the skull was seized as a prize of war and sent to Paris. In 1808 Georges Cuvier concluded that it belonged to a giant marine lizard related to monitor lizards but unlike any living animal, an idea that helped establish that species could become extinct. William Conybeare named it Mosasaurus, 'lizard of the Meuse', in 1822. The species lived around 82-66 million years ago, and the largest reached about 12 metres or more.",
 [('600 bottles of wine','In a 1799 account, Barthélemy Faujas de Saint-Fond wrote that the skull was retrieved for the French by twelve grenadiers in exchange for 600 bottles of wine; the story is often repeated but rests on this single account.'),
  ('Monsters and dragons','Before Cuvier, fossils of large unknown creatures were widely read as remains of giants, dragons or animals killed in the biblical Flood. The Maastricht skull became a key piece of evidence that whole worlds of animals had vanished.')],
 ['wiki:Mosasaurus','wiki:Georges_Cuvier'],'Mosasaurus',dateNote='Skull found 1778; seized 1795'),
X('ghent-just-judges',"The stolen Just Judges panel of the Ghent Altarpiece",H,'disputed',3,1934,['documentary (police and court records)','art-historical'],
 "The Just Judges is the lower left panel of the Ghent Altarpiece (Adoration of the Mystic Lamb), painted by Jan van Eyck and possibly his brother Hubert between about 1430 and 1432. During the night of 10 April 1934 it was stolen from St Bavo's Cathedral in Ghent. On 30 April the Bishop of Ghent received a ransom demand for one million Belgian francs; the Belgian government refused, and as a sign of good faith the thief returned the panel's reverse side, a grisaille of St John the Baptist. On 25 November 1934 Arsène Goedertier told his lawyer on his deathbed that he alone knew where the Mystic Lamb was, and that he would take the secret to his grave. Carbon copies of the ransom notes were found in his desk. The panel has never been found; it was replaced in 1945 by a copy made by Jef Van der Veken.",
 [('Goedertier the thief','The police concluded that Goedertier was the thief; one of his unsent notes said the panel rested in a place where neither he nor anyone else could take it away without attracting public attention.'),
  ('A wider plot','There is speculation that Goedertier could not have acted alone and had inside help, possibly from one of the cathedral\'s custodians, and amateur and official searches continue to be proposed (speculative).'),
  ('The copy','Van der Veken based his copy on a 16th-century copy by Michiel Coxie, and subtly marked it as a copy by giving one of the horsemen the face of King Leopold III.')],
 ['wiki:The_Just_Judges','wiki:Ghent_Altarpiece'],'Ghent Altarpiece',dateNote='Stolen 10-11 April 1934'),
X('van-meegeren-forgeries',"Han van Meegeren: the forger who fooled Göring",H,'confirmed',2,1937,['forensic (paint chemistry)','court records'],
 "Han van Meegeren (1889-1947), a Dutch painter dismissed by critics, set out to prove his talent by forging Dutch Golden Age paintings. He mixed phenol formaldehyde resin (Bakelite) into his paints and baked the canvases so the paint would harden as if centuries old. In 1937 the leading expert Abraham Bredius hailed his The Supper at Emmaus as 'the masterpiece of Johannes Vermeer of Delft', and it was bought for the Museum Boijmans in Rotterdam. In 1942 one of his fake Vermeers, Christ with the Adulteress, was acquired by Hermann Göring in exchange for 137 looted paintings. After the war Van Meegeren was arrested for selling Dutch cultural property to the Nazis; to escape a possible death penalty he confessed to forgery, and between July and December 1945 painted a new 'Vermeer' before court-appointed witnesses. A scientific commission led by Paul Coremans found 20th-century resins in the paint. In November 1947 he was sentenced to one year for forgery and fraud, but died of heart failure on 30 December 1947.",
 [('Folk hero','A Dutch opinion poll in October 1947 ranked Van Meegeren among the most popular people in the country, seen as the trickster who had fooled the experts and Göring.'),
  ('Self-made legend','The art historian Jonathan Lopez argued that this image was itself a forgery: Van Meegeren had written articles echoing Nazi and antisemitic rhetoric, and his trial defence, presenting the sale to Göring as a patriotic trick, was a masterpiece of self-invention.'),
  ('Doubters of the forgery','In the 1950s the Belgian expert Jean Decoen and the collector Daniël van Beuningen insisted that some of the works, including the Emmaus, were genuine Vermeers; courts and later analyses, including radioactive dating of the lead white and a 1977 forensic study, confirmed they were modern.')],
 ['wiki:Han_van_Meegeren','wiki:Abraham_Bredius'],'Han van Meegeren',end=1947,dateNote='Emmaus accepted as Vermeer 1937; confession 1945'),
X('akbar-ibadat-khana',"Akbar's House of Worship and the 'Divine Faith'",H,'confirmed',2,1575,['textual (Mughal chronicles)','architectural','Jesuit letters'],
 "The Mughal emperor Akbar (r. 1556-1605) built a new capital at Fatehpur Sikri from 1571, near the shrine of the Sufi Sheikh Salim Chishti who had predicted the birth of his son Jahangir; the city was largely abandoned after about 1585. In 1575 he built there the Ibadat Khana (House of Worship), where he held debates between Sunni and Shia Muslim scholars, Hindus, Jains, Zoroastrians, Jesuit missionaries from Goa and others. In 1582 he propounded the Din-i Ilahi ('Divine Faith' or 'Oneness of the Divine'), a syncretic set of beliefs and practices that drew on several of these traditions, with vegetarianism and non-violence among its ideals. Only around 19 followers are identified, and it lapsed after his death.",
 [('A new religion','Many Muslim scholars of the period denounced it as blasphemy and called Akbar an apostate, and some accounts describe him as leaving Islam to found a new faith.'),
  ('A discipleship and a policy','Some modern scholars argue it was a spiritual discipleship of Akbar\'s own beliefs rather than a full religion, its followers being called chelah (\'disciples\'), and that its core was the policy of sulh-i kul (\'universal peace\') used to govern a diverse empire.')],
 ['wiki:Ibadat_Khana','wiki:Din-i_Ilahi','wiki:Fatehpur_Sikri'],'Ibadat Khana',end=1605,dateNote='Ibadat Khana 1575; Din-i Ilahi 1582'),
X('akbar-dumb-house',"The 'dumb house': Akbar and the forbidden experiment",H,'disputed',3,1578,['textual (chronicles)'],
 "Rulers in several cultures are said to have tried to find humanity's 'natural' language by raising infants without hearing speech, which the scholar Roger Shattuck called the 'forbidden experiment'. Herodotus wrote that the Egyptian pharaoh Psamtik I (664-610 BCE) had a child raised in this way, and that its first word sounded like bekos, which meant 'bread' in Phrygian, so he concluded the Phrygians were older than the Egyptians. The monk Salimbene di Adam wrote that Emperor Frederick II (13th century) had infants nursed in silence, and that they all died. James IV of Scotland (r. 1488-1513) was said to have sent two children with a mute woman to the island of Inchkeith, and they reportedly spoke good Hebrew. The Mughal emperor Akbar, who held that speech comes from hearing, is recorded as having had children raised by mute nurses in a building that became known as the 'dumb house'; when he visited in 1582, the children made no speech at all.",
 [('Akbar\'s test probably real','Historians consider Akbar\'s experiment the most likely to be authentic, and its outcome supported his view that language is learned rather than innate.'),
  ('Tales with a moral','Some authors doubt that the experiments of Psamtik and James IV took place as told, and probably that of Frederick II too; Salimbene was hostile to Frederick and used the story to show his cruelty and curiosity.'),
  ('Modern echoes','Real cases of children raised in severe isolation, and debates over a language instinct, mean the question behind the stories is still discussed in linguistics, while such an experiment is now considered unethical.')],
 ['wiki:Language_deprivation_experiments','wiki:Psamtik_I'],'Akbar',dateNote='Akbar c. 1578-1582; Psamtik 7th century BCE'),
X('taj-mahal-tejo-mahalaya',"The 'Tejo Mahalaya' theory: was the Taj Mahal a Hindu temple?",H,'debunked',3,1965,['textual (Mughal records)','architectural','court rulings'],
 "The Taj Mahal in Agra was built from about 1632 by the Mughal emperor Shah Jahan as a mausoleum for his wife Mumtaz Mahal, on land given by Raja Jai Singh I in exchange for a palace in the centre of Agra. From 1965 the writer P. N. Oak argued in books such as 'The Taj Mahal was a Rajput Palace' and 'Taj Mahal: The True Story' (1989) that it was an older Hindu temple-palace dedicated to Shiva, 'Tejo Mahalaya', which Shah Jahan had taken over. Oak made similar claims about the Kaaba, Westminster Abbey and Vatican City.",
 [('Hidden temple','Supporters point to the Mughal chronicle Padshahnama\'s statement that a mansion of Jai Singh\'s family stood on the site as evidence of an earlier Hindu building; several court cases have been inspired by the theory.'),
  ('Pseudohistory','Historians reject the theory. The the Padshahnama and other records describe the acquisition of the land and construction of the tomb; the art historian Giles Tillotson called Oak\'s work a \'startling piece of pseudo-scholarship\'. India\'s Supreme Court dismissed Oak\'s petition in 2000, saying he had a \'bee in his bonnet\', and in 2017 the Archaeological Survey of India stated there was no evidence that the monument had been a temple.')],
 ['wiki:P._N._Oak','wiki:Taj_Mahal'],'Taj Mahal',dateNote='Theory from 1965; Taj Mahal built from c. 1632'),
X('koh-i-noor-curse',"The Koh-i-Noor: a diamond's journey and its 'curse'",M,'disputed',2,1526,['documentary','tradition'],
 "The Koh-i-Noor ('Mountain of Light') is one of the world's largest cut diamonds, now 105.6 carats. It first appears in the record in the late 15th or early 16th century: in 1526, after the First Battle of Panipat, Babur's son Humayun received a great diamond from the family of the ruler of Gwalior, and Babur wrote that its value could feed the whole world for a day. It later adorned Shah Jahan's Peacock Throne, was carried off to Persia by Nader Shah in 1739, passed to the Durrani rulers of Afghanistan and then to Ranjit Singh of the Sikh Empire in 1813. After the Second Anglo-Sikh War it was surrendered to Queen Victoria in 1849 by the 11-year-old Maharaja Duleep Singh, recut in 1852, and set in the crowns of British queens. India, Pakistan, Iran and Afghanistan have each claimed it.",
 [('The curse','A rumour that the stone was cursed, bringing violent ends to the men who owned it, may have begun in the Delhi Gazette and was repeated in the Illustrated London News; Queen Victoria herself expressed concern. A counter-rumour held that the curse affected only male rulers, and the diamond has since been worn only by female members of the royal family.'),
  ('Ancient origins','Some traditions identify it with diamonds in older Indian accounts, including a large diamond Alauddin Khalji acquired from the Kakatiya kingdom around 1310; historians note the link cannot be proven.'),
  ('A spoil of war','The Governor-General Lord Dalhousie treated the stone as a spoil of war; Britain says it was acquired legally under the Last Treaty of Lahore, while claimant countries call it taken unjustly. Queen Victoria herself later became uneasy about the way the diamond had been acquired.')],
 ['wiki:Koh-i-Noor','wiki:Duleep_Singh'],'Koh-i-Noor',dateNote='Recorded with the Mughals from 1526'),
]
